PIN_MIN_TIME = 0.1
RESEND_HOST_TIME = 0.3 + PIN_MIN_TIME
MAX_SCHEDULE_TIME = 5.0

class PrinterOutputPin:

    def __init__(self, config):
        self.printer = config.get_printer()
        ppins = self.printer.lookup_object("pins")
        self.is_pwm = config.getboolean("pwm", False)
        if self.is_pwm:
            self.mcu_pin = ppins.setup_pin("pwm", config.get("pin"))
            cycle_time = config.getfloat("cycle_time", 0.1, above=0.0, maxval=MAX_SCHEDULE_TIME)
            hardware_pwm = config.getboolean("hardware_pwm", False)
            self.mcu_pin.setup_cycle_time(cycle_time, hardware_pwm)
            self.scale = config.getfloat("scale", 1.0, above=0.0)
        else:
            self.mcu_pin = ppins.setup_pin("digital_out", config.get("pin"))
            self.scale = 1.0
        self.last_print_time = 0.0
        self.reactor = self.printer.get_reactor()
        self.resend_timer = None
        self.resend_interval = 0.0
        max_mcu_duration = config.getfloat("maximum_mcu_duration", 0.0, minval=0.5,
          maxval=MAX_SCHEDULE_TIME)
        self.mcu_pin.setup_max_duration(max_mcu_duration)
        if max_mcu_duration:
            config.deprecate("maximum_mcu_duration")
            self.resend_interval = max_mcu_duration - RESEND_HOST_TIME
        static_value = config.getfloat("static_value", None, minval=0.0,
          maxval=(self.scale))
        if static_value is not None:
            config.deprecate("static_value")
            self.last_value = self.shutdown_value = static_value / self.scale
        else:
            self.last_value = config.getfloat("value",
              0.0, minval=0.0, maxval=(self.scale)) / self.scale
            self.shutdown_value = config.getfloat("shutdown_value",
              0.0, minval=0.0, maxval=(self.scale)) / self.scale
        self.mcu_pin.setup_start_value(self.last_value, self.shutdown_value)
        pin_name = config.get_name().split()[1]
        gcode = self.printer.lookup_object("gcode")
        gcode.register_mux_command("SET_PIN", "PIN", pin_name, (self.cmd_SET_PIN),
          desc=(self.cmd_SET_PIN_help))

    def get_status(self, eventtime):
        return {"value": (self.last_value)}

    def _set_pin(self, print_time, value, is_resend=False):
        if value == self.last_value:
            if not is_resend:
                return
            print_time = max(print_time, self.last_print_time + PIN_MIN_TIME)
            if self.is_pwm:
                self.mcu_pin.set_pwm(print_time, value)
            else:
                self.mcu_pin.set_digital(print_time, value)
            self.last_value = value
            self.last_print_time = print_time
            if self.resend_interval:
                if self.resend_timer is None:
                    self.resend_timer = self.reactor.register_timer(self._resend_current_val, self.reactor.NOW)

    cmd_SET_PIN_help = "Set the value of an output pin"

    def cmd_SET_PIN(self, gcmd):
        value = gcmd.get_float("VALUE", minval=0.0, maxval=(self.scale))
        value /= self.scale
        if not self.is_pwm:
            if value not in (0.0, 1.0):
                raise gcmd.error("Invalid pin value")
        pin = gcmd.get_command_parameters().get("PIN")
        if pin == "LED":
            systime = self.reactor.monotonic()
            print_time = self.mcu_pin.get_mcu().estimated_print_time(systime)
            self._set_pin(print_time, value)
            return
        toolhead = self.printer.lookup_object("toolhead")
        toolhead.register_lookahead_callback(lambda print_time: self._set_pin(print_time, value))

    def _resend_current_val(self, eventtime):
        if self.last_value == self.shutdown_value:
            self.reactor.unregister_timer(self.resend_timer)
            self.resend_timer = None
            return self.reactor.NEVER
        systime = self.reactor.monotonic()
        print_time = self.mcu_pin.get_mcu().estimated_print_time(systime)
        time_diff = self.last_print_time + self.resend_interval - print_time
        if time_diff > 0.0:
            return systime + time_diff
        self._set_pin(print_time + PIN_MIN_TIME, self.last_value, True)
        return systime + self.resend_interval


def load_config_prefix(config):
    return PrinterOutputPin(config)

